{
  "title": "Downtown Roots and a Coyoacán Bite",
  "summary": "A slower day in Mexico City, swapping Teotihuacan and Pujol for a Chapultepec stroll and a Roma Norte wander, while keeping the Templo Mayor and Coyoacán market.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The old city heart stays put: a morning with the Aztecs before the sun gets serious.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "A calm, vegetarian-friendly lunch near the Templo Mayor, with halal options for the crew."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "A green, easy wander in Chapultepec replaces the long pyramid trip, keeping the afternoon light."
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "Roma Norte's street life gives the photographers and culture lovers a fresh frame for the day."
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "The Coyoacán market stays as the late-afternoon anchor, full of street food and local colour."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A relaxed vegetarian dinner in Roma Norte closes the day without the long Pujol affair."
    }
  ]
}

